import Navbar from "@/components/Navbar";
import Hero from "@/components/Hero";
import Features from "@/components/Features";
import Partners from "@/components/Partners";
import CTA from "@/components/CTA";
import Location from "@/components/Location";
import Footer from "@/components/Footer";

async function getLandingPageData() {
  const res = await fetch('http://127.0.0.1:8000/api/landing-page', { cache: 'no-store' });
  if (!res.ok) {
    throw new Error('Failed to fetch data');
  }
  return res.json();
}

export default async function Home() {
  let data = null;
  try {
    data = await getLandingPageData();
  } catch (e) {
    console.error("API error:", e);
  }

  if (!data) return <div>Loading... Please ensure Laravel API is running on port 8000.</div>;

  return (
    <main className="min-h-screen">
      <Navbar brandName={data.settings.navbar_brand} />
      <Hero data={data.hero} />
      <Features features={data.features} />
      <Partners partners={data.partners} />
      <CTA data={data.cta} />
      <Location data={data.location} />
      <Footer copyright={data.settings.footer_copyright} />
    </main>
  );
}
